@verbatim
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Bangun Karsa – Kontraktor Profesional</title>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@500;600;700;800&family=Public+Sans:wght@300;400;500;600&display=swap" rel="stylesheet">
<style>
:root{--nv:#0F2A4A;--nv2:#173F69;--tl:#0E9AA7;--tl2:#0B7F89;--co:#FF6B57;--co2:#D9503E;--sk:#DCEFFB;--sk2:#EEF7FD;--ink:#0B1B2E;--mu:#5B6B7F;--ln:#D5E3EE;--h:'Archivo',system-ui,sans-serif;--b:'Public Sans',system-ui,sans-serif;
box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
*,*::before,*::after{box-sizing:inherit}
html{scroll-behavior:smooth}
body{margin:0;background:#fff;color:var(--ink);font:400 16px/1.65 var(--b);overflow-x:hidden}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4,p{margin:0}
.w{max-width:1200px;margin:auto;padding:0 24px}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 26px;border-radius:6px;border:0;background:var(--nv);color:#fff;font:600 15px var(--h);letter-spacing:.01em;cursor:pointer;transition:.25s}
.btn:hover,.btn:focus-visible{background:var(--tl);outline:none;transform:translateY(-2px)}
.btn.c{background:var(--co)}.btn.c:hover{background:var(--co2)}
.btn.o{background:transparent;color:var(--nv);box-shadow:inset 0 0 0 2px var(--nv)}.btn.o:hover{background:var(--nv);color:#fff}
.btn.wh{background:#fff;color:var(--nv)}.btn.wh:hover{background:var(--co);color:#fff}
.ey{font:700 12.5px var(--h);letter-spacing:.18em;text-transform:uppercase;color:var(--tl)}
header.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:60;background:rgba(255,255,255,.98);border-bottom:1px solid var(--ln)}
header.top .w{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-top:14px;padding-bottom:14px}
.lg{font:800 23px var(--h);letter-spacing:-.03em;color:var(--nv);display:flex;align-items:center;gap:10px}
.lg i{width:30px;height:30px;background:var(--nv);position:relative;clip-path:polygon(0 100%,0 30%,50% 0,100% 30%,100% 100%)}
.lg i::after{content:"";position:absolute;left:34%;right:34%;bottom:0;height:55%;background:var(--co)}
nav ul{display:flex;gap:6px;list-style:none;margin:0;padding:0}
nav a.l{display:block;padding:9px 16px;font:600 15px var(--h);color:var(--mu);border-radius:6px;position:relative}
nav a.l:hover{color:var(--nv);background:var(--sk2)}
nav a.l.on{color:var(--nv)}nav a.l.on::after{content:"";position:absolute;left:16px;right:16px;bottom:2px;height:3px;background:var(--co);border-radius:2px}
#mb{display:none;background:#fff;border:1.5px solid var(--ln);border-radius:6px;width:44px;height:44px;font-size:24px;cursor:pointer;color:var(--nv)}
#bangun-menu{position:fixed;left:0;right:0;top:calc(72px + env(safe-area-inset-top,0px));bottom:0;z-index:55;background:#fff;border-bottom:1px solid var(--ln);padding:18px 24px 24px;overflow-y:auto;visibility:hidden;opacity:0;pointer-events:none;transform:translateY(-110%);transition:.35s}
#bangun-menu.open{visibility:visible;opacity:1;pointer-events:auto;transform:none}
#bangun-menu ul{display:flex;flex-direction:column;gap:4px;list-style:none;margin:0;padding:0}
#bangun-menu a{display:block;padding:15px 0;border-bottom:1px solid var(--ln);font:700 18px var(--h)}
@media(max-width:860px){#mb{display:block}header.top nav:not(#bangun-menu){display:none}header.top .btn{display:none}}
.view{display:none}.view.on{display:block;animation:fd .5s}@keyframes fd{from{opacity:0;transform:translateY(12px)}}
/* hero */
.hero{background:linear-gradient(160deg,var(--sk),#fff 70%);clip-path:polygon(0 0,100% 0,100% 94%,0 100%);padding:70px 0 120px}
.hero .w{display:grid;grid-template-columns:1.05fr .95fr;gap:30px;align-items:center}
.hero h1{font:800 clamp(40px,5.6vw,80px)/1 var(--h);letter-spacing:-.045em;color:var(--nv);margin:14px 0 20px}
.hero h1 span{color:var(--co)}
.hero p{max-width:520px;font-size:18px;color:var(--mu)}
.hc{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}
.hs svg{width:100%;display:block}
.fr{animation:rs .7s cubic-bezier(.2,.8,.2,1) both}@keyframes rs{from{opacity:0;transform:translateY(46px)}}
.sw{animation:sw 6s ease-in-out infinite;transform-origin:319px 40px}@keyframes sw{50%{transform:rotate(1.5deg)}}
@media(max-width:860px){.hero .w{grid-template-columns:1fr}.hs{max-width:380px;margin:auto}}
.st{background:var(--nv);color:#fff;margin-top:-40px;position:relative}
.st .w{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;padding-top:44px;padding-bottom:44px}
.st b{display:block;font:800 clamp(34px,4.4vw,56px)/1 var(--h);letter-spacing:-.03em}.st b em{font-style:normal;color:var(--co)}
.st span{font-size:14px;color:#A8BDD3}
@media(max-width:700px){.st .w{grid-template-columns:1fr 1fr}}
section.s{padding:96px 0}
.hd{max-width:700px;margin-bottom:46px}
.hd h2{font:800 clamp(30px,4vw,52px)/1.04 var(--h);letter-spacing:-.04em;color:var(--nv);margin:10px 0 12px}
.hd p{color:var(--mu)}
.sv{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.sc{border:1px solid var(--ln);border-radius:14px;padding:22px;background:#fff;cursor:pointer;text-align:left;font:inherit;color:inherit;transition:.3s;display:flex;flex-direction:column;gap:6px}
.sc:hover{border-color:var(--tl);box-shadow:0 22px 40px -22px rgba(15,42,74,.4);transform:translateY(-5px)}
.sc .im{background:var(--sk2);border-radius:10px;margin-bottom:10px}.sc svg{width:100%;display:block}
.sc h3{font:700 20px var(--h);color:var(--nv)}.sc p{font-size:14.5px;color:var(--mu)}.sc em{font:700 14px var(--h);font-style:normal;color:var(--co);margin-top:auto;padding-top:8px}
@media(max-width:960px){.sv{grid-template-columns:1fr 1fr}}@media(max-width:560px){.sv{grid-template-columns:1fr}}
.pr{display:grid;grid-template-columns:repeat(5,1fr);gap:0;counter-reset:s}
.pr div{padding:0 18px 0 0;position:relative;counter-increment:s}
.pr div::before{content:"0" counter(s);display:grid;place-items:center;width:46px;height:46px;border-radius:50%;background:var(--co);color:#fff;font:800 16px var(--h);margin-bottom:14px;position:relative;z-index:1}
.pr div::after{content:"";position:absolute;top:22px;left:46px;right:0;height:2px;background:repeating-linear-gradient(90deg,var(--tl) 0 8px,transparent 8px 14px)}
.pr div:last-child::after{display:none}
.pr h3{font:700 18px var(--h);color:var(--nv)}.pr p{font-size:14px;color:var(--mu);margin-top:4px}
@media(max-width:860px){.pr{grid-template-columns:1fr;gap:24px}.pr div::after{display:none}}
.band{background:linear-gradient(120deg,var(--nv),var(--nv2));color:#fff;border-radius:20px;padding:clamp(34px,5vw,64px);display:flex;justify-content:space-between;align-items:center;gap:30px;flex-wrap:wrap;position:relative;overflow:hidden}
.band::after{content:"";position:absolute;right:-60px;top:-60px;width:260px;height:260px;border-radius:50%;background:var(--tl);opacity:.35}
.band h2{font:800 clamp(28px,3.6vw,46px)/1.05 var(--h);letter-spacing:-.03em;max-width:560px;position:relative}.band div{position:relative;display:flex;gap:12px;flex-wrap:wrap}
.qs{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.qs blockquote{margin:0;padding:28px;background:var(--sk2);border-left:4px solid var(--tl);border-radius:0 12px 12px 0;font-size:16.5px}
.qs cite{display:block;margin-top:12px;font:700 13.5px var(--h);font-style:normal;color:var(--nv)}
@media(max-width:860px){.qs{grid-template-columns:1fr}}
/* pages */
.ph{background:var(--sk);padding:60px 0 50px;border-bottom:1px solid var(--ln)}
.ph h1{font:800 clamp(34px,5vw,64px)/1 var(--h);letter-spacing:-.04em;color:var(--nv);margin:10px 0}
.ph p{max-width:600px;color:var(--mu)}
.cr{font-size:13.5px;color:var(--mu);margin-bottom:14px}.cr a{color:var(--tl);font-weight:600}.cr a:hover{text-decoration:underline}
.fc{display:flex;gap:8px;flex-wrap:wrap;margin:34px 0 28px}
.fc button{padding:9px 20px;border-radius:99px;border:1.5px solid var(--ln);background:#fff;font:600 14.5px var(--h);cursor:pointer;color:var(--mu);transition:.2s}
.fc button:hover{border-color:var(--tl)}.fc button[aria-pressed=true]{background:var(--nv);color:#fff;border-color:var(--nv)}
.pg{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.pc{border:1px solid var(--ln);border-radius:16px;overflow:hidden;display:flex;flex-direction:column;transition:.3s;background:#fff}
.pc:hover{box-shadow:0 26px 50px -26px rgba(15,42,74,.5);transform:translateY(-6px);border-color:var(--tl)}
.pc .im{background:var(--sk2);padding:10px}.pc svg{width:100%;display:block}
.pc .tx{padding:20px 22px 24px;display:flex;flex-direction:column;gap:6px;flex:1}
.tg{display:inline-block;width:fit-content;font:700 11.5px var(--h);letter-spacing:.1em;text-transform:uppercase;padding:3px 10px;border-radius:99px;background:var(--sk);color:var(--tl2)}
.pc h3{font:700 21px/1.15 var(--h);color:var(--nv)}.pc small{color:var(--mu);font-size:14px}.pc em{margin-top:auto;padding-top:8px;font:700 14.5px var(--h);font-style:normal;color:var(--co)}
@media(max-width:960px){.pg{grid-template-columns:1fr 1fr}}@media(max-width:600px){.pg{grid-template-columns:1fr}}
.dh{display:grid;grid-template-columns:1.05fr .95fr;gap:40px;align-items:center}
.dh h1{font:800 clamp(32px,4.4vw,58px)/1.02 var(--h);letter-spacing:-.04em;color:var(--nv);margin:12px 0}
.dh .im{background:#fff;border-radius:18px;padding:16px;border:1px solid var(--ln)}.dh svg{width:100%;display:block}
.fa{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--ln);border:1px solid var(--ln);border-radius:12px;overflow:hidden;margin:34px 0 0}
.fa div{background:#fff;padding:20px}.fa small{display:block;font:600 11.5px var(--h);letter-spacing:.12em;text-transform:uppercase;color:var(--mu)}.fa b{font:700 21px var(--h);color:var(--nv)}
@media(max-width:860px){.dh{grid-template-columns:1fr}.fa{grid-template-columns:1fr 1fr}}
.dg{display:grid;grid-template-columns:1fr 1fr;gap:50px;margin-top:60px}
.dg h2{font:800 28px var(--h);letter-spacing:-.03em;color:var(--nv);margin-bottom:18px}
.dg ul{list-style:none;padding:0;margin:0}.dg li{padding:11px 0 11px 30px;border-top:1px solid var(--ln);position:relative}.dg li::before{content:"";position:absolute;left:0;top:19px;width:14px;height:8px;border-left:2.5px solid var(--tl);border-bottom:2.5px solid var(--tl);transform:rotate(-45deg)}
.tl{display:grid;gap:12px}.tl div{display:grid;grid-template-columns:1fr auto;gap:4px 14px;align-items:center}.tl b{font-weight:600}.tl span{font:500 13.5px var(--b);color:var(--mu)}.tl i{grid-column:1/-1;height:10px;border-radius:6px;background:var(--sk);overflow:hidden;position:relative}.tl i::after{content:"";position:absolute;inset:0 auto 0 0;width:var(--w);background:linear-gradient(90deg,var(--tl),var(--co));border-radius:6px}
@media(max-width:860px){.dg{grid-template-columns:1fr}}
.pn{display:flex;justify-content:space-between;gap:16px;margin-top:60px;padding-top:26px;border-top:1px solid var(--ln);flex-wrap:wrap}
/* estimasi */
.eg{display:grid;grid-template-columns:1fr 1fr;gap:34px;align-items:start}
.ep{border:1px solid var(--ln);border-radius:18px;padding:32px;background:#fff}
.ep label{display:block;font:700 12.5px var(--h);letter-spacing:.12em;text-transform:uppercase;color:var(--mu);margin:20px 0 8px}.ep label:first-child{margin-top:0}
.ep select,.fm input,.fm select,.fm textarea{width:100%;padding:13px 14px;border:1.5px solid var(--ln);border-radius:8px;font:400 15.5px var(--b);background:#fff;color:var(--ink);outline:none}
.ep select:focus,.fm input:focus,.fm select:focus,.fm textarea:focus{border-color:var(--tl)}
.ep input[type=range]{width:100%;accent-color:var(--co)}.ep output{font:800 34px var(--h);color:var(--nv);letter-spacing:-.03em}
.er{background:var(--nv);color:#fff;border-radius:18px;padding:34px;position:sticky;top:96px}
.er small{color:#A8BDD3;font-size:13.5px}.er .rg{font:800 clamp(28px,3.6vw,44px)/1.05 var(--h);letter-spacing:-.03em;margin:6px 0 4px}
.er .du{color:var(--co);font:700 16px var(--h);margin-bottom:22px}
.sb{display:flex;height:16px;border-radius:8px;overflow:hidden;margin-bottom:16px}.sb i{transition:width .6s}
.lg2{display:grid;gap:8px;margin-bottom:22px}.lg2 div{display:flex;justify-content:space-between;gap:10px;font-size:14.5px}.lg2 span{display:flex;align-items:center;gap:10px;color:#D5E3EE}.lg2 i{width:11px;height:11px;border-radius:3px}.lg2 b{font-weight:600;font-family:var(--h)}
.er .nt{font-size:12.5px;color:#A8BDD3;margin-top:16px;line-height:1.5}
@media(max-width:900px){.eg{grid-template-columns:1fr}.er{position:static}}
/* kontak */
.kg{display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:start}
.fm{border:1px solid var(--ln);border-radius:18px;padding:32px}
.fm label{display:block;font:700 12.5px var(--h);letter-spacing:.12em;text-transform:uppercase;color:var(--mu);margin:16px 0 6px}.fm label:first-child{margin-top:0}
.fm .r2{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.fm .btn{margin-top:24px;width:100%;justify-content:center}
.if{background:var(--sk2);border-radius:18px;padding:30px;margin-bottom:20px}.if h3{font:700 20px var(--h);color:var(--nv);margin-bottom:10px}.if p{font-size:15px;color:var(--mu)}.if p+p{margin-top:6px}
details{border-bottom:1px solid var(--ln);padding:16px 0}summary{cursor:pointer;font:700 16.5px var(--h);color:var(--nv);list-style:none;display:flex;justify-content:space-between;gap:12px}summary::after{content:"+";color:var(--co);font-size:22px;line-height:1;transition:.3s}details[open] summary::after{transform:rotate(45deg)}details p{margin-top:10px;color:var(--mu);font-size:15px}
@media(max-width:860px){.kg{grid-template-columns:1fr}.fm .r2{grid-template-columns:1fr}}
footer{background:var(--ink);color:#B6C6D8;padding:60px 0 30px;margin-top:40px}
.fg{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:40px}footer h4{font:700 12.5px var(--h);letter-spacing:.16em;text-transform:uppercase;color:var(--co);margin-bottom:10px}footer p,footer li{font-size:14.5px}footer ul{list-style:none;padding:0;margin:0}footer li{margin:5px 0}footer a:hover{color:#fff}
.cp{font-size:12.5px;margin-top:34px;padding-top:20px;border-top:1px solid #1d3047;color:#7E91A6;max-width:820px}
@media(max-width:760px){.fg{grid-template-columns:1fr}}
/* rail + chat */
.rl{position:fixed;right:0;top:50%;transform:translateY(-50%);z-index:70;display:flex;flex-direction:column;border-radius:12px 0 0 12px;overflow:hidden;box-shadow:-6px 8px 30px rgba(15,42,74,.3)}
.rl a,.rl button{width:56px;height:56px;border:0;background:var(--nv);color:#fff;cursor:pointer;display:grid;place-items:center;font:700 10px var(--h);letter-spacing:.06em;transition:.25s;padding:0;gap:0;position:relative}
.rl svg{width:22px;height:22px;stroke:#fff;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;margin-bottom:-6px}
.rl a:hover,.rl button:hover{background:var(--tl)}.rl .co{background:var(--co)}.rl .co:hover{background:var(--co2)}.rl .wa{background:#1FA855}
#chat{position:fixed;right:70px;top:50%;z-index:80;width:min(370px,calc(100vw - 90px));height:min(500px,76vh);background:#fff;border-radius:16px;box-shadow:0 24px 70px rgba(15,42,74,.4);display:none;flex-direction:column;overflow:hidden;transform:translateY(-50%)}
#chat.on{display:flex;animation:ci .35s}@keyframes ci{from{opacity:0;transform:translate(30px,-50%)}}
#chat header{background:var(--nv);color:#fff;padding:14px 18px;display:flex;justify-content:space-between;align-items:center}#chat header b{font:700 16px var(--h)}#chat header small{display:block;color:#7ED6DD;font-size:12px}#chat header button{background:none;border:0;color:#fff;font-size:22px;cursor:pointer}
#ms{flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:9px;background:var(--sk2);font-size:14.5px}
.m{max-width:88%;padding:9px 14px;border-radius:12px;line-height:1.5;animation:fd .3s}.m.b{background:#fff;border:1px solid var(--ln);align-self:flex-start}.m.u{background:var(--nv);color:#fff;align-self:flex-end}
.cs{display:flex;flex-wrap:wrap;gap:6px;padding:8px 14px 0}.cs button{padding:6px 12px;border:1.5px solid var(--tl);background:#fff;color:var(--tl2);border-radius:99px;font:600 12.5px var(--h);cursor:pointer}.cs button:hover{background:var(--tl);color:#fff}
#cf{display:flex;gap:8px;padding:10px 14px}#cf input{flex:1;padding:11px 14px;border:1.5px solid var(--ln);border-radius:8px;font:400 14.5px var(--b);outline:none;min-width:0}#cf button{padding:0 16px;border:0;border-radius:8px;background:var(--co);color:#fff;cursor:pointer}
#cw{display:block;text-align:center;padding:10px;background:#1FA855;color:#fff;font:700 13.5px var(--h)}
:focus-visible{outline:2px solid var(--co);outline-offset:3px}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
</head>
<body>
<header class="top"><div class="w"><a class="lg" href="#beranda"><i></i>Bangun Karsa</a>
<nav id="nv"><ul><li><a class="l" href="#beranda" data-r="beranda">Beranda</a></li><li><a class="l" href="#proyek" data-r="proyek">Proyek</a></li><li><a class="l" href="#estimasi" data-r="estimasi">Estimasi biaya</a></li><li><a class="l" href="#kontak" data-r="kontak">Kontak</a></li></ul></nav>
<a class="btn c" href="#kontak">Minta penawaran</a><button id="mb" type="button" aria-label="Buka menu navigasi" aria-controls="bangun-menu" aria-expanded="false">☰</button></div></header>
<nav id="bangun-menu" aria-hidden="true"><ul><li><a href="#beranda">Beranda</a></li><li><a href="#proyek">Proyek</a></li><li><a href="#estimasi">Estimasi biaya</a></li><li><a href="#kontak">Kontak</a></li></ul></nav>

<main>
<!-- BERANDA -->
<div class="view" id="v-beranda">
<section class="hero"><div class="w"><div><span class="ey">Kontraktor bangunan dan renovasi</span><h1>Membangun dengan perencanaan yang <span>terukur.</span></h1><p>Dari rumah tinggal sampai gedung komersial, kami mengerjakan dengan jadwal jelas, anggaran transparan, dan laporan progres yang rutin.</p><div class="hc"><a class="btn c" href="#estimasi">Hitung estimasi biaya</a><a class="btn o" href="#proyek">Lihat proyek kami</a></div></div><div class="hs" id="hs"></div></div></section>
<div class="st"><div class="w"><div><b>12<em>+</em></b><span>tahun pengalaman</span></div><div><b>150<em>+</em></b><span>proyek terselesaikan</span></div><div><b>40<em>+</em></b><span>tenaga ahli dan mandor</span></div><div><b>100<em>%</em></b><span>progres dilaporkan berkala</span></div></div></div>
<section class="s"><div class="w"><div class="hd"><span class="ey">Layanan</span><h2>Empat bidang yang kami kuasai</h2><p>Pilih bidang untuk melihat proyek yang pernah kami kerjakan.</p></div><div class="sv" id="sv"></div></div></section>
<section class="s" style="background:var(--sk2)"><div class="w"><div class="hd"><span class="ey">Cara kerja</span><h2>Lima tahap, tanpa kejutan.</h2></div>
<div class="pr"><div><h3>Konsultasi</h3><p>Kebutuhan, lahan, dan anggaran dibahas bersama.</p></div><div><h3>Survei dan RAB</h3><p>Survei lokasi, lalu rencana anggaran biaya tertulis.</p></div><div><h3>Kontrak</h3><p>Lingkup, jadwal, dan termin pembayaran disepakati.</p></div><div><h3>Pelaksanaan</h3><p>Pengerjaan dengan laporan progres berkala.</p></div><div><h3>Serah terima</h3><p>Pemeriksaan akhir dan masa pemeliharaan.</p></div></div></div></section>
<section class="s"><div class="w"><div class="hd"><span class="ey">Kata klien</span><h2>Proyek selesai, hubungan berlanjut.</h2></div><div class="qs"><blockquote>Progresnya selalu dilaporkan, jadi kami tidak perlu menebak-nebak di lapangan.<cite>Pak Hendra · Pemilik ruko</cite></blockquote><blockquote>Biaya akhir sangat dekat dengan RAB di awal. Itu yang paling kami hargai.<cite>Ibu Maya · Pemilik rumah</cite></blockquote><blockquote>Tim rapi, disiplin soal keselamatan kerja, dan responsif.<cite>PT Contoh Maju · Klien industri</cite></blockquote></div>
<div class="band" style="margin-top:70px"><h2>Punya rencana proyek? Mulai dari estimasi awal.</h2><div><a class="btn c" href="#estimasi">Hitung estimasi</a><a class="btn wh" href="#kontak">Jadwalkan survei</a></div></div></div></section>
