<script>
/* ===== KONFIGURASI: nomor WA format internasional tanpa + dan tanpa 0 di depan ===== */
const WA_NUMBER="6281234567890",BRAND="Bangun Karsa";
const $=i=>document.getElementById(i),wl=t=>"https://wa.me/"+WA_NUMBER+"?text="+encodeURIComponent(t);
const fm=n=>n>=1e9?"Rp "+(n/1e9).toFixed(2).replace(".",",")+" miliar":"Rp "+Math.round(n/1e6).toLocaleString("id-ID")+" juta";
function replaceMarkup(el,markup){const range=document.createRange();range.selectNodeContents(el);range.deleteContents();el.append(range.createContextualFragment(markup))}
rw.href=wl("Halo "+BRAND+", saya ingin konsultasi proyek.");
/* isometrik */
const NV="#0F2A4A",BL=["#2F6A9C","#1B4670","#DCEFFB"],CO=["#FF6B57","#D9503E","#FFB3A6"],TE=["#13A8B5","#0B7F89","#9FE4EA"];
const P=(a,b,c,o)=>[o.x+(a-b)*.866*o.u,o.y+(a+b)*.5*o.u-c*o.u];
const pl=(p,f,s)=>`<polygon points="${p.map(q=>q[0].toFixed(1)+","+q[1].toFixed(1)).join(" ")}" fill="${f}" ${s===0?'stroke="none"':`stroke="${NV}" stroke-width="1.3" stroke-linejoin="round"`}/>`;
function bx(o,x,y,w,d,z,h,c,win){const T=[P(x,y,z+h,o),P(x+w,y,z+h,o),P(x+w,y+d,z+h,o),P(x,y+d,z+h,o)],L=[P(x,y+d,z,o),P(x+w,y+d,z,o),P(x+w,y+d,z+h,o),P(x,y+d,z+h,o)],R=[P(x+w,y,z,o),P(x+w,y+d,z,o),P(x+w,y+d,z+h,o),P(x+w,y,z+h,o)];
let s=pl(L,c[0])+pl(R,c[1])+pl(T,c[2]);
if(win){const n=Math.max(2,Math.round(w*1.4)),m=Math.max(2,Math.round(d*1.4));
for(let i=0;i<n;i++)s+=pl([P(x+(i+.22)*w/n,y+d,z+.28*h,o),P(x+(i+.78)*w/n,y+d,z+.28*h,o),P(x+(i+.78)*w/n,y+d,z+.72*h,o),P(x+(i+.22)*w/n,y+d,z+.72*h,o)],win,0);
for(let i=0;i<m;i++)s+=pl([P(x+w,y+(i+.22)*d/m,z+.28*h,o),P(x+w,y+(i+.78)*d/m,z+.28*h,o),P(x+w,y+(i+.78)*d/m,z+.72*h,o),P(x+w,y+(i+.22)*d/m,z+.72*h,o)],win,0)}
return s}
const WN="#BFE3F5";
function thumb(t){const o={x:180,y:112,u:24};const gd=(w,d)=>pl([P(-.8,-.8,0,o),P(w+.8,-.8,0,o),P(w+.8,d+.8,0,o),P(-.8,d+.8,0,o)],"#0E9AA7",0).replace('/>',' opacity=".13"/>');let s='<svg viewBox="0 0 360 250" aria-hidden="true">';
if(t==="rumah")s+=gd(4,3)+bx(o,0,0,4,3,0,1.6,BL,WN)+bx(o,.3,.3,3.2,2.4,1.6,1.2,BL,WN)+bx(o,.1,.1,3.6,2.8,2.8,.2,CO);
if(t==="ruko")s+=gd(5,3)+bx(o,0,0,5,3,0,3,BL,WN)+bx(o,0,0,5,3,3,.2,CO);
if(t==="gudang")s+=gd(6,3.4)+bx(o,0,0,6,3.4,0,1.8,BL,"#9FE4EA")+bx(o,0,0,6,3.4,1.8,.25,TE);
if(t==="kantor")s+=gd(3,3)+bx(o,0,0,3,3,0,3.4,BL,WN)+bx(o,.6,.6,1.8,1.8,3.4,.6,CO);
if(t==="renov"){s+=gd(4,3)+bx(o,0,0,4,3,0,1.8,BL,WN);[[4,3],[0,3],[4,0]].forEach(([a,b])=>{const p=P(a,b,0,o),q=P(a,b,2.7,o);s+=`<path d="M${p[0]} ${p[1]}L${q[0]} ${q[1]}" stroke="#FF6B57" stroke-width="3"/>`});[.9,1.8,2.7].forEach(z=>{const p=P(0,3,z,o),q=P(4,3,z,o),r=P(4,0,z,o);s+=`<path d="M${p[0]} ${p[1]}L${q[0]} ${q[1]}L${r[0]} ${r[1]}" stroke="#FF6B57" stroke-width="2.4" fill="none"/>`})}
if(t==="industri")s+=gd(5.8,3)+bx(o,0,0,5,3,0,1.6,BL,"#9FE4EA")+bx(o,5.1,.5,.6,.6,0,3.2,CO)+bx(o,0,0,5,3,1.6,.2,TE);
return s+"</svg>"}
function hero(){const o={x:225,y:290,u:26};let s='<svg viewBox="0 0 460 430" aria-hidden="true">'+pl([P(-1,-1,0,o),P(7,-1,0,o),P(7,5.2,0,o),P(-1,5.2,0,o)],"#0E9AA7",0).replace('/>',' opacity=".14"/>');
for(let i=0;i<9;i++)s+=`<g class="fr" style="animation-delay:${i*.16}s">${bx(o,0,0,3.4,3.4,i*.9,.9,BL,i%4===3?"#9FE4EA":WN)}</g>`;
const a=P(4.8,.4,0,o),b=P(4.8,.4,10.4,o),c=P(1,.4,10.4,o),d=P(6.4,.4,10.4,o),e=P(2.2,.4,10.4,o),f=P(2.2,.4,9.2,o);
s+=`<path d="M${a[0]} ${a[1]}L${b[0]} ${b[1]}" stroke="#FF6B57" stroke-width="5"/><g class="sw"><path d="M${c[0]} ${c[1]}L${d[0]} ${d[1]}M${b[0]} ${b[1]}L${c[0]+10} ${c[1]-22}L${d[0]-6} ${d[1]}" stroke="#FF6B57" stroke-width="3.5" fill="none"/><path d="M${e[0]} ${e[1]}L${f[0]} ${f[1]}" stroke="${NV}" stroke-width="2"/><rect x="${f[0]-8}" y="${f[1]}" width="16" height="10" fill="${NV}"/></g></svg>`;return s}
replaceMarkup(hs,hero());
/* proyek */
const CT=[["all","Semua"],["rumah","Rumah tinggal"],["renov","Renovasi"],["komersial","Komersial"],["industri","Industri"]];
const PJ=[
{n:"Rumah Tinggal Modern 2 Lantai",c:"rumah",t:"rumah",l:"180 m²",d:"7 bulan",v:"Rp 1,2 miliar",ds:"Rumah keluarga dua lantai dengan desain terbuka dan pencahayaan alami.",sc:["Pekerjaan struktur beton bertulang","Arsitektur dan finishing interior","Instalasi listrik dan plumbing","Taman dan carport"],st:[["Perencanaan dan izin",12],["Struktur",35],["Arsitektur dan MEP",30],["Finishing",18],["Serah terima",5]]},
{n:"Ruko Tiga Lantai",c:"komersial",t:"ruko",l:"240 m²",d:"9 bulan",v:"Rp 2,4 miliar",ds:"Bangunan ruko tiga lantai dengan area usaha di bawah dan hunian di atas.",sc:["Struktur dan fasad","Instalasi listrik tiga fase","Sistem plumbing dan sanitasi","Finishing lantai usaha"],st:[["Perencanaan dan izin",10],["Struktur",38],["Arsitektur dan MEP",30],["Finishing",17],["Serah terima",5]]},
{n:"Renovasi Total Rumah Lama",c:"renov",t:"renov",l:"120 m²",d:"4 bulan",v:"Rp 520 juta",ds:"Pembongkaran sebagian, penataan ulang denah, dan penggantian instalasi lama.",sc:["Pembongkaran terkontrol","Penguatan struktur","Penggantian atap dan plafon","Finishing menyeluruh"],st:[["Survei dan perencanaan",15],["Pembongkaran",15],["Struktur dan arsitektur",40],["Finishing",25],["Serah terima",5]]},
{n:"Gudang dan Kantor Pabrik",c:"industri",t:"gudang",l:"1.200 m²",d:"10 bulan",v:"Rp 6,8 miliar",ds:"Gudang berbentang lebar dengan area kantor dan fasilitas pendukung.",sc:["Pondasi dan struktur baja","Lantai kerja industri","Instalasi listrik dan proteksi kebakaran","Kantor dan fasilitas pekerja"],st:[["Perencanaan dan izin",10],["Pondasi dan baja",40],["Atap, dinding, MEP",28],["Finishing",17],["Serah terima",5]]},
{n:"Kantor Cabang Empat Lantai",c:"komersial",t:"kantor",l:"900 m²",d:"12 bulan",v:"Rp 8,5 miliar",ds:"Gedung kantor cabang dengan lobi, ruang rapat, dan area kerja terbuka.",sc:["Struktur beton dan fasad kaca","Sistem tata udara dan listrik","Interior lobi dan ruang rapat","Lansekap dan parkir"],st:[["Perencanaan dan izin",12],["Struktur",36],["Fasad, MEP",30],["Interior",17],["Serah terima",5]]},
{n:"Renovasi Fasad dan Interior Toko",c:"renov",t:"renov",l:"150 m²",d:"3 bulan",v:"Rp 380 juta",ds:"Peremajaan tampilan toko dengan jadwal kerja malam agar usaha tetap berjalan.",sc:["Fasad dan papan nama","Penataan interior dan rak","Pencahayaan toko","Pekerjaan malam hari"],st:[["Survei dan desain",15],["Pembongkaran",15],["Fasad dan interior",45],["Finishing",20],["Serah terima",5]]}];
const SVC=[["Pembangunan rumah","rumah","Dari desain sampai serah terima kunci.","rumah"],["Renovasi","renov","Perbaikan dan penataan ulang bangunan lama.","renov"],["Gedung komersial","komersial","Ruko, kantor, dan ruang usaha.","kantor"],["Industri","industri","Gudang dan fasilitas pabrik.","gudang"]];
let CAT="all";
replaceMarkup(sv,SVC.map(s=>`<button class="sc" data-c="${s[1]}"><div class="im">${thumb(s[3])}</div><h3>${s[0]}</h3><p>${s[2]}</p><em>Lihat proyek →</em></button>`).join(""));
sv.onclick=e=>{const b=e.target.closest(".sc");if(b){CAT=b.dataset.c;location.hash="proyek"}};
function lst(){replaceMarkup(fc,CT.map(c=>`<button aria-pressed="${c[0]===CAT}" data-c="${c[0]}">${c[1]}</button>`).join(""));
replaceMarkup(pg,PJ.map((p,i)=>[p,i]).filter(([p])=>CAT==="all"||p.c===CAT).map(([p,i])=>`<a class="pc" href="#proyek-${i+1}"><div class="im">${thumb(p.t)}</div><div class="tx"><span class="tg">${CT.find(c=>c[0]===p.c)[1]}</span><h3>${p.n}</h3><small>${p.l} · ${p.d}</small><em>Lihat detail proyek →</em></div></a>`).join(""))}
fc.onclick=e=>{const b=e.target.closest("button");if(b){CAT=b.dataset.c;lst()}};
function det(i){const p=PJ[i],tot=p.st.reduce((a,s)=>a+s[1],0),pv=PJ[(i+5)%6],nx=PJ[(i+1)%6];
replaceMarkup($("v-detail"),`<div class="ph"><div class="w dh"><div><div class="cr"><a href="#beranda">Beranda</a> / <a href="#proyek">Proyek</a> / ${p.n}</div><span class="ey">${CT.find(c=>c[0]===p.c)[1]}</span><h1>${p.n}</h1><p>${p.ds}</p><div class="hc"><a class="btn c" target="_blank" rel="noopener" href="${wl(`Halo ${BRAND}, saya tertarik dengan proyek seperti "${p.n}". Mohon konsultasi dan estimasi untuk kebutuhan saya.`)}">Konsultasi proyek serupa</a><a class="btn o" href="#estimasi">Hitung estimasi</a></div></div><div class="im">${thumb(p.t)}</div></div></div>
<section class="s" style="padding-top:50px"><div class="w"><div class="fa"><div><small>Luas bangunan</small><b>${p.l}</b></div><div><small>Durasi</small><b>${p.d}</b></div><div><small>Nilai (contoh)</small><b>${p.v}</b></div><div><small>Kategori</small><b>${CT.find(c=>c[0]===p.c)[1]}</b></div></div>
<div class="dg"><div><h2>Lingkup pekerjaan</h2><ul>${p.sc.map(x=>`<li>${x}</li>`).join("")}</ul></div><div><h2>Tahapan pelaksanaan</h2><div class="tl">${p.st.map(s=>`<div><b>${s[0]}</b><span>${Math.round(s[1]/100*parseInt(p.d)*30/7)} minggu</span><i style="--w:${s[1]/Math.max(...p.st.map(z=>z[1]))*100}%"></i></div>`).join("")}</div></div></div>
<div class="pn"><a class="btn o" href="#proyek-${(i+5)%6+1}">← ${pv.n}</a><a class="btn o" href="#proyek-${(i+1)%6+1}">${nx.n} →</a></div></div></section>`)}
/* estimasi */
const BP={rumah:4200000,ruko:4800000,gudang:3200000,renov:2600000},BD={rumah:[["Struktur",35,"#0F2A4A"],["Arsitektur",20,"#0E9AA7"],["MEP",15,"#7FB8D9"],["Finishing",22,"#FF6B57"],["Overhead dan margin",8,"#9AA7B6"]],renov:[["Struktur",15,"#0F2A4A"],["Arsitektur",30,"#0E9AA7"],["MEP",20,"#7FB8D9"],["Finishing",28,"#FF6B57"],["Overhead dan margin",7,"#9AA7B6"]]};
BD.ruko=BD.rumah;BD.gudang=[["Struktur",42,"#0F2A4A"],["Arsitektur",16,"#0E9AA7"],["MEP",18,"#7FB8D9"],["Finishing",16,"#FF6B57"],["Overhead dan margin",8,"#9AA7B6"]];
function est(){const j=ej.value,L=+el.value,f=+ef.value,q=+eq.value;eo.textContent=L.toLocaleString("id-ID")+" m²";const v=BP[j]*L*f*q,lo=v*.9,hi=v*1.15,mo=Math.max(2,Math.round(2+L/(j==="gudang"?180:j==="renov"?70:50)));
er.textContent=fm(lo)+" – "+fm(hi);ed.textContent="Perkiraan durasi sekitar "+mo+" bulan";const B=BD[j];
replaceMarkup(eb,B.map(b=>`<i style="width:${b[1]}%;background:${b[2]}"></i>`).join(""));replaceMarkup(elg,B.map(b=>`<div><span><i style="background:${b[2]}"></i>${b[0]} (${b[1]}%)</span><b>${fm(v*b[1]/100)}</b></div>`).join(""));
ew.href=wl(`Halo ${BRAND}, saya ingin RAB detail untuk ${ej.options[ej.selectedIndex].text}, luas ${L} m², ${ef.options[ef.selectedIndex].text}, finishing ${eq.options[eq.selectedIndex].text}. Estimasi awal ${fm(lo)} sampai ${fm(hi)}, durasi sekitar ${mo} bulan. Mohon jadwal survei.`)}
[ej,el,ef,eq].forEach(e=>e.oninput=est);est();
/* kontak */
const dd=new Date();dd.setDate(dd.getDate()+1);kd.min=dd.toISOString().slice(0,10);
function kt_(){const d=kd.value?new Date(kd.value+"T00:00").toLocaleDateString("id-ID",{weekday:"long",day:"numeric",month:"long"}):"(belum dipilih)";
kw.href=wl(`Halo ${BRAND}, saya ${kn.value||"calon klien"}${kp.value?" dari "+kp.value:""}. Saya ingin survei untuk: ${kt.value}. Lokasi: ${kl.value||"(belum diisi)"}. Anggaran: ${kb.value}. Tanggal survei: ${d}.${km.value?" Catatan: "+km.value:""}`)}
[kn,kp,kt,kb,kd,kl,km].forEach(e=>e.oninput=kt_);kt_();
/* router */
const TT={beranda:"Beranda",proyek:"Proyek",estimasi:"Estimasi biaya",kontak:"Kontak"};
function route(){let h=location.hash.slice(1)||"beranda",v=h,m=h.match(/^proyek-(\d+)$/);
if(m&&PJ[+m[1]-1]){det(+m[1]-1);v="detail"}else if(!TT[h])h=v="beranda";
document.querySelectorAll(".view").forEach(e=>e.classList.toggle("on",e.id==="v-"+v));
if(v==="proyek")lst();
document.querySelectorAll("nav a.l").forEach(a=>a.classList.toggle("on",a.dataset.r===(v==="detail"?"proyek":h)));
document.title=(v==="detail"?PJ[+m[1]-1].n:TT[h])+" – Bangun Karsa";
closeBangunMenu();
window.scrollTo(0,0)}
const mb=$("mb"),bangunMenu=$("bangun-menu");
function closeBangunMenu(){bangunMenu.classList.remove("open");bangunMenu.setAttribute("aria-hidden","true");mb.setAttribute("aria-expanded","false");mb.setAttribute("aria-label","Buka menu navigasi")}
function toggleBangunMenu(){const open=!bangunMenu.classList.contains("open");bangunMenu.classList.toggle("open",open);bangunMenu.setAttribute("aria-hidden",open?"false":"true");mb.setAttribute("aria-expanded",open?"true":"false");mb.setAttribute("aria-label",open?"Tutup menu navigasi":"Buka menu navigasi")}
addEventListener("hashchange",route);
mb.onclick=toggleBangunMenu;
bangunMenu.querySelectorAll("a").forEach(a=>a.onclick=closeBangunMenu);
addEventListener("keydown",e=>{if(e.key==="Escape")closeBangunMenu()});
route();
/* chat */
const KB=[
[/harga|biaya|estimasi|rab|berapa|anggaran/,()=>"Gunakan halaman Estimasi biaya untuk kisaran awal berdasarkan jenis bangunan, luas, dan kualitas. RAB yang akurat memerlukan survei lokasi dan gambar kerja.",["Survei lokasi","Pembayaran"]],
[/survei|konsultasi|jadwal|datang/,()=>"Isi formulir di halaman Kontak untuk menjadwalkan survei, atau lanjut ke WhatsApp. Tim kami menghubungi dalam satu hari kerja.",["Lanjut ke WhatsApp"]],
[/bayar|pembayaran|termin|dp/,()=>"Pembayaran umumnya bertahap (termin) sesuai progres pekerjaan, dan disepakati tertulis dalam kontrak.",["Durasi pengerjaan","Garansi"]],
[/lama|durasi|waktu|kapan selesai/,()=>"Durasi bergantung luas dan jenis bangunan. Contohnya rumah dua lantai sekitar 7 bulan. Kalkulator di halaman Estimasi memberi gambaran awal.",["Estimasi biaya"]],
[/izin|pbg|imb|legal/,()=>"Pendampingan perizinan bangunan sesuai ketentuan setempat dapat disediakan. Tim kami menjelaskan kebutuhannya saat konsultasi.",["Survei lokasi"]],
[/garansi|pemeliharaan|retensi/,()=>"Masa pemeliharaan dan garansi pekerjaan dijelaskan tertulis dalam kontrak.",["Pembayaran"]],
[/proyek|portofolio|contoh|pengalaman/,()=>"Lihat halaman Proyek untuk contoh pekerjaan rumah, renovasi, komersial, dan industri, lengkap dengan lingkup dan tahapannya.",["Estimasi biaya"]],
[/k3|keselamatan|aman/,()=>"Keselamatan kerja menjadi bagian dari pelaksanaan proyek, mengikuti ketentuan yang berlaku. Detail prosedur dijelaskan saat konsultasi.",["Survei lokasi"]],
[/halo|hai|hi\b|pagi|siang|malam/,()=>"Halo, selamat datang di Bangun Karsa. Ada rencana proyek yang ingin dikonsultasikan?",["Estimasi biaya","Survei lokasi","Pembayaran","Proyek"]]];
const lg=[];function say(t,c){const d=document.createElement("div");d.className="m "+c;d.textContent=t;ms.append(d);ms.scrollTop=1e9;if(c==="u")lg.push(t)}
function chips(a){cs.replaceChildren();a.forEach(v=>{const b=document.createElement("button");b.textContent=v;b.onclick=()=>ask(v);cs.append(b)})}
function waU(){cw.href=wl(`Halo ${BRAND}, saya menghubungi dari website.`+(lg.length?` Pertanyaan saya: ${lg.join("; ")}.`:" Saya ingin konsultasi proyek."))}
function ask(t){say(t,"u");if(/whatsapp|\bwa\b|admin|manusia|teknisi|sales/i.test(t)){setTimeout(()=>{say("Baik, klik tombol WhatsApp di bawah. Pertanyaan Anda ikut terkirim.","b");waU()},300);return}
const m=KB.find(([r])=>r.test(t.toLowerCase()));setTimeout(()=>{if(m){say(m[1](),"b");chips(m[2])}else{say("Pertanyaan ini lebih tepat dijawab tim kami langsung. Klik WhatsApp di bawah, pertanyaan Anda ikut terkirim.","b");chips(["Estimasi biaya","Survei lokasi","Proyek"])}waU()},350)}
cf.onsubmit=e=>{e.preventDefault();const v=ci.value.trim();if(v){ci.value="";ask(v)}};
let fi=true;oc.onclick=()=>{chat.classList.toggle("on");if(chat.classList.contains("on")&&fi){fi=false;say("Selamat datang. Saya konsultan virtual Bangun Karsa, bisa membantu soal layanan, estimasi, dan survei. Angka di sini contoh dan bukan penawaran final.","b");chips(["Estimasi biaya","Survei lokasi","Pembayaran","Proyek"]);waU()}};x.onclick=()=>chat.classList.remove("on");
</script>
